import { useContext, useState } from "react";
import { AuthContext } from "../../context/authContext";
import Friends from "../../assets/1.png";
import Groups from "../../assets/2.png";
import Gallery from "../../assets/8.png";
import Videos from "../../assets/9.png";
import Messages from "../../assets/10.png";
import Addfrnds from "../../assets/a.png";
import "./leftBar.scss";

const LeftBar = () => {
  const { currentUser } = useContext(AuthContext);
  const [showFriends, setShowFriends] = useState(false);

  // Mock friends data (replace with authContext.js or API if available)
  const friends = [
    {
      id: 1,
      name: "John Doe",
      profilePic: "https://images.pexels.com/photos/1036623/pexels-photo-1036623.jpeg?auto=compress&cs=tinysrgb&w=1600",
    },
    {
      id: 2,
      name: "Jane Doe",
      profilePic: "https://images.pexels.com/photos/1036623/pexels-photo-1036623.jpeg?auto=compress&cs=tinysrgb&w=1600",
    },
    {
      id: 3,
      name: "Sam Smith",
      profilePic: "https://images.pexels.com/photos/1036623/pexels-photo-1036623.jpeg?auto=compress&cs=tinysrgb&w=1600",
    },
  ];

  const handleFriendsClick = () => {
    setShowFriends(!showFriends);
  };

  return (
    <div className="leftBar">
      <div className="container">
        <div className="menu">
          <div className="user">
            <img src={currentUser.profilePic} alt={`${currentUser.name}'s profile`} />
            <span>{currentUser.name}</span>
          </div>
          <div className="item" onClick={handleFriendsClick} style={{ cursor: "pointer" }}>
            <img src={Friends} alt="Friends icon" />
            <span>Friends</span>
          </div>
          {showFriends && (
            <div className="friends-list">
              <h3>Your Friends</h3>
              {friends.length > 0 ? (
                friends.map((friend) => (
                  <div className="friend" key={friend.id}>
                    <img src={friend.profilePic} alt={`${friend.name}'s profile`} />
                    <span>{friend.name}</span>
                  </div>
                ))
              ) : (
                <p>No friends found.</p>
              )}
            </div>
          )}
          <div className="item">
            <img src={Groups} alt="Groups icon" />
            <span>Groups</span>
          </div>
        </div>
        <hr />
        <div className="menu">
          <span>Your shortcuts</span>
          <div className="item">
            <img src={Videos} alt="Videos icon" />
            <span>Videos</span>
          </div>
          <div className="item">
            <img src={Gallery} alt="Gallery icon" />
            <span>Photos</span>
          </div>
          <div className="item">
            <img src={Videos} alt="Videos icon" />
            <span>Videos</span>
          </div>
          <div className="item">
            <img src={Messages} alt="Messages icon" />
            <span>Messages</span>
          </div>
        </div>
        <hr />
      </div>
    </div>
  );
};

export default LeftBar;
